// AccelGroupsActivate wraps gtk_accel_groups_activate
// 
// The function takes the following parameters:
// 
// 	- object gobject.Object: the #GObject, usually a #GtkWindow, on which
//     to activate the accelerator 
// 	- accelKey uint: accelerator keyval from a key event 
// 	- accelMods gdk.ModifierType: keyboard state mask from a key event 
// 
// The function returns the following values:
// 
// 	- goret bool 
//
// Finds the first accelerator in any #GtkAccelGroup attached
// to @object that matches @accel_key and @accel_mods, and
// activates that accelerator.
func AccelGroupsActivate(object gobject.Object, accelKey uint, accelMods gdk.ModifierType) bool {
	var carg1 *C.GObject        // in, none, converted
	var carg2 C.guint           // in, none, casted
	var carg3 C.GdkModifierType // in, none, casted
	var cret  C.gboolean        // return

	carg1 = (*C.GObject)(gobject.UnsafeObjectToGlibNone(object))
	carg2 = C.guint(accelKey)
	carg3 = C.GdkModifierType(accelMods)

	cret = C.gtk_accel_groups_activate(carg1, carg2, carg3)
	runtime.KeepAlive(object)
	runtime.KeepAlive(accelKey)
	runtime.KeepAlive(accelMods)

	var goret bool

	if cret != 0 {
		goret = true
	}

	return goret
}

