//   but = gtk_button_new_with_label (text);
//   g_signal_connect_swapped (but, "clicked",
//                             G_CALLBACK (gtk_object_destroy),
//                             win);
//   gtk_container_add (GTK_CONTAINER (win), but);
// 
//   gtk_widget_show_all (win);
// 
