// foo_bar_set_property (GObject         *object,
//                       guint            prop_id,
//                       const GValue    *value,
//                       GParamSpec      *pspec)
// {
//   FooBar *bar = FOO_BAR (object);
//   FooBarPrivate *priv = FOO_BAR_GET_PRIVATE (bar);
// 
//   switch (prop_id)
