// 
// |[&lt;!-- language="C" --&gt;
// static GtkPrintSettings *settings = NULL;
// static GtkPageSetup *page_setup = NULL;
// 
// static void
// do_page_setup (void)
// {
//   GtkPageSetup *new_page_setup;
// 
//   if (settings == NULL)
//     settings = gtk_print_settings_new ();
// 
//   new_page_setup = gtk_print_run_page_setup_dialog (GTK_WINDOW (main_window),
//                                                     page_setup, settings);
// 
//   if (page_setup)
