func unsafeWrapContainer(base *gobject.ObjectInstance) *ContainerInstance {
	return &ContainerInstance{
		WidgetInstance: WidgetInstance{
			InitiallyUnownedInstance: gobject.InitiallyUnownedInstance{
				ObjectInstance: *base,
			},
			ImplementorIfaceInstance: atk.ImplementorIfaceInstance{
				Instance: *base,
			},
		},
		BuildableInstance: BuildableInstance{
			Instance: *base,
		},
	}
}

func marshalContainerInstance(p unsafe.Pointer) (any, error) {
	return unsafeWrapContainer(gobject.ValueFromNative(p).Object()), nil
}

