// 
// |[&lt;!-- language="plain" --&gt;
// spinbutton.horizontal
// ├── undershoot.left
// ├── undershoot.right
// ├── entry
// │   ╰── ...
// ├── button.down
// ╰── button.up
// ]|
// 
// |[&lt;!-- language="plain" --&gt;
// spinbutton.vertical
// ├── undershoot.left
// ├── undershoot.right
// ├── button.up
// ├── entry
// │   ╰── ...
// ╰── button.down
// ]|
