func unsafeWrapTextView(base *gobject.ObjectInstance) *TextViewInstance {
	return &TextViewInstance{
		ContainerInstance: ContainerInstance{
			WidgetInstance: WidgetInstance{
				InitiallyUnownedInstance: gobject.InitiallyUnownedInstance{
					ObjectInstance: *base,
				},
				ImplementorIfaceInstance: atk.ImplementorIfaceInstance{
					Instance: *base,
				},
			},
			BuildableInstance: BuildableInstance{
				Instance: *base,
			},
		},
		ScrollableInstance: ScrollableInstance{
			Instance: *base,
		},
	}
}

func marshalTextViewInstance(p unsafe.Pointer) (any, error) {
	return unsafeWrapTextView(gobject.ValueFromNative(p).Object()), nil
}

// UnsafeTextViewFromGlibNone is used to convert raw GtkTextView pointers to go while taking a reference and attaching a finalizer. This is used by the bindings internally.
func UnsafeTextViewFromGlibNone(c unsafe.Pointer) TextView {
	return gobject.UnsafeObjectFromGlibNone(c).(TextView)
}

// UnsafeTextViewFromGlibFull is used to convert raw GtkTextView pointers to go while attaching a finalizer. This is used by the bindings internally.
func UnsafeTextViewFromGlibFull(c unsafe.Pointer) TextView {
	return gobject.UnsafeObjectFromGlibFull(c).(TextView)
}

func (t *TextViewInstance) upcastToGtkTextView() *TextViewInstance {
	return t
}

