// &lt;object class="GtkWindow"&gt;
//   &lt;accel-groups&gt;
//     &lt;group name="accelgroup1"/&gt;
//   &lt;/accel-groups&gt;
//   &lt;initial-focus name="thunderclap"/&gt;
// &lt;/object&gt;
// 
// ...
// 
// &lt;object class="GtkAccelGroup" id="accelgroup1"/&gt;
