	//   gtk_widget_show_all (vbox);
	// 
	//   gtk_window_set_geometry_hints (GTK_WINDOW (window),
	// 	  			    NULL,
	// 				    &amp;size_hints,
	// 				    GDK_HINT_MIN_SIZE |
	// 				    GDK_HINT_BASE_SIZE |
	// 				    GDK_HINT_RESIZE_INC);
	// 
	//   if (argc &gt; 1)
	//     {
	//       gboolean res;
	//       res = gtk_window_parse_geometry (GTK_WINDOW (window),
	//                                        argv[1]);
	//       if (! res)
