func unsafeWrapWindow(base *gobject.ObjectInstance) *WindowInstance {
	return &WindowInstance{
		BinInstance: BinInstance{
			ContainerInstance: ContainerInstance{
				WidgetInstance: WidgetInstance{
					InitiallyUnownedInstance: gobject.InitiallyUnownedInstance{
						ObjectInstance: *base,
					},
					ImplementorIfaceInstance: atk.ImplementorIfaceInstance{
						Instance: *base,
					},
				},
				BuildableInstance: BuildableInstance{
					Instance: *base,
				},
			},
		},
	}
}

func marshalWindowInstance(p unsafe.Pointer) (any, error) {
	return unsafeWrapWindow(gobject.ValueFromNative(p).Object()), nil
}

// UnsafeWindowFromGlibNone is used to convert raw GtkWindow pointers to go while taking a reference and attaching a finalizer. This is used by the bindings internally.
func UnsafeWindowFromGlibNone(c unsafe.Pointer) Window {
	return gobject.UnsafeObjectFromGlibNone(c).(Window)
}

// UnsafeWindowFromGlibFull is used to convert raw GtkWindow pointers to go while attaching a finalizer. This is used by the bindings internally.
func UnsafeWindowFromGlibFull(c unsafe.Pointer) Window {
	return gobject.UnsafeObjectFromGlibFull(c).(Window)
}

func (w *WindowInstance) upcastToGtkWindow() *WindowInstance {
	return w
}

// UnsafeWindowToGlibNone is used to convert the instance to it's C value GtkWindow. This is used by the bindings internally.
func UnsafeWindowToGlibNone(c Window) unsafe.Pointer {
	return gobject.UnsafeObjectToGlibNone(c)
}

// UnsafeWindowToGlibFull is used to convert the instance to it's C value GtkWindow, while removeing the finalizer. This is used by the bindings internally.
func UnsafeWindowToGlibFull(c Window) unsafe.Pointer {
	return gobject.UnsafeObjectToGlibFull(c)
}

// NewWindowInstance wraps gtk_window_new
// 
// The function takes the following parameters:
// 
// 	- typ WindowType: type of window 
// 
// The function returns the following values:
// 
// 	- goret Widget 
//
// Creates a new #GtkWindow, which is a toplevel window that can
// contain other widgets. Nearly always, the type of the window should
// be #GTK_WINDOW_TOPLEVEL. If you’re implementing something like a
// popup menu from scratch (which is a bad idea, just use #GtkMenu),
// you might use #GTK_WINDOW_POPUP. #GTK_WINDOW_POPUP is not for
// dialogs, though in some other toolkits dialogs are called “popups”.
// In GTK+, #GTK_WINDOW_POPUP means a pop-up menu or pop-up tooltip.
// On X11, popup windows are not controlled by the
// [window manager][gtk-X11-arch].
// 
// If you simply want an undecorated window (no window borders), use
// gtk_window_set_decorated(), don’t use #GTK_WINDOW_POPUP.
// 
// All top-level windows created by gtk_window_new() are stored in
// an internal top-level window list.  This list can be obtained from
// gtk_window_list_toplevels().  Due to Gtk+ keeping a reference to
// the window internally, gtk_window_new() does not return a reference
// to the caller.
// 
// To delete a #GtkWindow, call gtk_widget_destroy().
func NewWindowInstance(typ WindowType) Widget {
	var carg1 C.GtkWindowType // in, none, casted
	var cret  *C.GtkWidget    // return, none, converted

	carg1 = C.GtkWindowType(typ)

	cret = C.gtk_window_new(carg1)
	runtime.KeepAlive(typ)

	var goret Widget

	goret = UnsafeWidgetFromGlibNone(unsafe.Pointer(cret))

	return goret
}

